// MigrationFunc executes an explicit, transactional migration step on an unresolved Document.
type MigrationFunc func(d *nativeconfig.Document) error

// Migrations provides typed, versioned migration dispatch.
type Migrations struct {
	steps map[int]MigrationFunc
}

func NewMigrations() *Migrations {
	return &Migrations{steps: make(map[int]MigrationFunc)}
}

func (m *Migrations) Register(fromVersion int, fn MigrationFunc) {
	m.steps[fromVersion] = fn
}

func (m *Migrations) Apply(d *nativeconfig.Document, targetVersion int) error {
	if d == nil {
		return fmt.Errorf("nil document")
	}
	if !d.HasVersion {
		d.Version = 0
		d.HasVersion = true
	}
	for d.Version < targetVersion {
		fn, ok := m.steps[d.Version]
		if !ok {
			return fmt.Errorf("no migration registered from version %d to %d", d.Version, d.Version+1)
		}
		cloned := d.Clone()
		if err := fn(cloned); err != nil {
			return fmt.Errorf("migration step %d -> %d failed: %w", d.Version, d.Version+1, err)
		}
		cloned.Version = d.Version + 1
		*d = *cloned
	}
	return nil
}

// Sample returns a sample Document illustrating defaults as active entries
// and examples as documentation comments.
func Sample() *nativeconfig.Document {
	d := &nativeconfig.Document{
		Version:    SchemaVersion,
		HasVersion: true,
		Items: []nativeconfig.Item{
			nativeconfig.Version{},
			nativeconfig.Blank{},
			nativeconfig.Comment{Kind: nativeconfig.UserComment, Text: "Single # comments belong to you; ## documentation is schema-managed."},
			nativeconfig.Comment{Kind: nativeconfig.DocumentationComment, Text: "Examples below are comments, not active values or defaults."},
			nativeconfig.Blank{},
		},
	}
	{
		sec := &nativeconfig.Section{Name: "worker default"}
		sec.Items = append(sec.Items, nativeconfig.Blank{})
		tmp := &nativeconfig.Document{}
		tmp.AddSection(sec)
		for _, line := range strings.Split(strings.TrimSuffix(nativeconfig.Format(tmp), "\n"), "\n") {
			text := ""
			if line != "" {
				text = "  " + line
			}
			d.Items = append(d.Items, nativeconfig.Comment{Kind: nativeconfig.DocumentationComment, Text: text})
		}
		d.Items = append(d.Items, nativeconfig.Blank{})
	}
	return d
}
